// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Bonjour! French is spoken on five continents by over 300 million people. Let's start with greetings.","blocks":[{"t":"p","text":"Greetings: bonjour (hello, good day), bonsoir (good evening), salut (hi or bye, informal). Goodbyes: au revoir, à bientôt (see you soon), à demain (see you tomorrow)."},{"t":"key","text":"Use tu (informal \"you\") with friends, family and kids. Use vous (formal \"you\") with adults you don't know, teachers, and when speaking to more than one person."},{"t":"p","text":"Politeness matters in French culture: always say bonjour when entering a shop, and use s'il vous plaît (please, formal), merci (thank you), and de rien (you're welcome)."},{"t":"p","text":"Asking how someone is: Comment ça va? / Ça va? — Ça va bien, merci. Et toi? (formal: Comment allez-vous?)"}]},{"say":"Let's introduce ourselves and learn the sounds that make French beautiful.","blocks":[{"t":"p","text":"Introductions: Comment tu t'appelles? (What's your name?) — Je m'appelle Léa. Enchanté(e) (Nice to meet you). J'ai quinze ans (I'm 15). J'habite à Paris (I live in Paris)."},{"t":"key","text":"Pronunciation tips:"},{"t":"list","items":["Final consonants are usually silent (petit, Paris), except often C, R, F and L (\"careful\").","Liaison: a normally silent final consonant is pronounced before a word starting with a vowel: les amis sounds like \"lay-zah-mee.\"","Nasal vowels (on, an, in, un) are pronounced partly through the nose.","The French r is made in the back of the throat."]},{"t":"p","text":"Accents change pronunciation or meaning: é (aigu), è (grave), ê (circonflexe), ç (cédille makes c sound like s)."}]}],[{"say":"Numbers in French have some fun surprises, especially after 60. Let's count!","blocks":[{"t":"p","text":"Numbers 1–10: un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix. Then onze (11), douze (12), vingt (20), trente (30), quarante (40), cinquante (50), soixante (60), cent (100)."},{"t":"key","text":"French counts in twenties above 60: soixante-dix (70 = sixty-ten), quatre-vingts (80 = four twenties), quatre-vingt-dix (90 = four twenties ten)."},{"t":"p","text":"Days (lundi, mardi, mercredi, jeudi, vendredi, samedi, dimanche) and months (janvier, février, mars…) are not capitalized."},{"t":"p","text":"Dates: le + number + month: le cinq mai (May 5th). The first uses premier: le premier janvier."},{"t":"ex","problem":"How do you say 75?","steps":["75 = 60 + 15"],"answer":"soixante-quinze"}]},{"say":"Quelle heure est-il? Let's learn to tell time. French often uses the 24-hour clock!","blocks":[{"t":"key","text":"Il est + number + heure(s): Il est une heure (1:00), Il est trois heures (3:00)."},{"t":"list","items":["Add minutes after the hour: Il est deux heures dix (2:10).","et quart (quarter past), et demie (half past), moins le quart (quarter to).","midi (noon), minuit (midnight)."]},{"t":"p","text":"The 24-hour clock is common for schedules: 15h00 = quinze heures (3:00 p.m.)."},{"t":"p","text":"To say when something happens: à + time: Le cours est à huit heures."},{"t":"ex","problem":"How do you say \"It's 4:30\"?","steps":["Il est quatre heures + et demie"],"answer":"Il est quatre heures et demie."}]}],[{"say":"Every French noun is masculine or feminine. Learn each noun with its article!","blocks":[{"t":"key","text":"Definite articles (the): le (masculine), la (feminine), l' (before a vowel or silent h), les (plural). Indefinite articles (a, some): un, une, des."},{"t":"p","text":"Gender often can't be guessed, so learn each noun with its article. Some patterns: nouns ending in -tion, -té and -ette are usually feminine; -ment and -age are usually masculine."},{"t":"p","text":"Plurals usually add -s (silent): le livre → les livres. Words ending in -eau add -x: le bureau → les bureaux."},{"t":"ex","problem":"Give \"a pencil\" and \"the school\"","steps":["Crayon is masculine: un crayon","École starts with a vowel: l'école"],"answer":"un crayon, l'école"}]},{"say":"Let's describe ourselves and others. French adjectives agree with the nouns they describe.","blocks":[{"t":"key","text":"Adjectives agree in gender and number: add -e for feminine and -s for plural: grand, grande, grands, grandes. Adjectives already ending in -e don't change for gender: jeune, timide."},{"t":"p","text":"Most adjectives come after the noun (une fille intelligente), but BAGS adjectives (Beauty, Age, Goodness, Size) come before: une belle maison, un petit chien, un bon livre."},{"t":"p","text":"Irregular feminine forms: beau → belle, nouveau → nouvelle, vieux → vieille, gentil → gentille, sportif → sportive."},{"t":"p","text":"Use être (to be): je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont."}]}],[{"say":"Three irregular verbs appear constantly in French: être, avoir and aller. Let's master them.","blocks":[{"t":"key","text":"avoir (to have): j'ai, tu as, il/elle a, nous avons, vous avez, ils/elles ont."},{"t":"p","text":"aller (to go): je vais, tu vas, il/elle va, nous allons, vous allez, ils/elles vont."},{"t":"p","text":"French uses avoir for age: J'ai seize ans (I'm 16). Expressions with avoir: avoir faim (to be hungry), avoir soif (thirsty), avoir peur (afraid)."},{"t":"p","text":"Aller + infinitive expresses the near future: Je vais étudier (I'm going to study)."},{"t":"p","text":"To make a sentence negative, wrap ne…pas around the verb: Je ne suis pas fatigué."},{"t":"ex","problem":"Say \"We are going to eat.\"","steps":["nous + allons + infinitive"],"answer":"Nous allons manger."}]},{"say":"Most French verbs end in -er and follow one pattern. Learn it and you can use hundreds of verbs!","blocks":[{"t":"key","text":"Regular -er verbs (parler): drop -er and add -e, -es, -e, -ons, -ez, -ent: je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent. The -e, -es and -ent endings are silent."},{"t":"p","text":"Regular -ir verbs (finir): je finis, tu finis, il finit, nous finissons, vous finissez, ils finissent."},{"t":"p","text":"Regular -re verbs (vendre): je vends, tu vends, il vend, nous vendons, vous vendez, ils vendent."},{"t":"p","text":"Je becomes j' before a vowel: j'aime (I like)."},{"t":"ex","problem":"Conjugate \"aimer\" for \"we\"","steps":["Drop -er: aim-"],"answer":"nous aimons"}]}],[{"say":"Let's talk about your school and family in French.","blocks":[{"t":"p","text":"School words: le cours (class), le professeur (teacher), les maths, les sciences, l'histoire, l'anglais, la récré (break), l'emploi du temps (schedule)."},{"t":"p","text":"Family: la mère, le père, les parents, le frère, la sœur, les grands-parents, l'oncle, la tante, le cousin/la cousine."},{"t":"key","text":"Possessive adjectives agree with the noun possessed, not the owner: mon père, ma mère, mes parents; ton/ta/tes (your); son/sa/ses (his or her). Use mon instead of ma before a vowel: mon amie."},{"t":"p","text":"Express likes with aimer: J'aime les maths, mais je n'aime pas l'histoire. Use definite articles after aimer, adorer and détester."}]},{"say":"Bon appétit! French food culture is famous worldwide. Let's order at a café.","blocks":[{"t":"p","text":"Meals: le petit-déjeuner (breakfast), le déjeuner (lunch), le dîner (dinner). Food: le pain, le fromage, le croissant, la viande, le poulet, les légumes, l'eau, le jus, le café."},{"t":"key","text":"Partitive articles express \"some\" for things you can't count: du (masculine), de la (feminine), de l' (vowel), des (plural): Je voudrais du pain et de la confiture. After a negative, they become de: Je ne mange pas de viande."},{"t":"p","text":"Polite ordering: Je voudrais… (I would like…), L'addition, s'il vous plaît (The check, please)."},{"t":"ex","problem":"Order some cheese and some water politely.","steps":["fromage is masculine: du fromage; eau: de l'eau"],"answer":"Je voudrais du fromage et de l'eau, s'il vous plaît."}]}]];
export default text;
